import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { rejectApplicationHandler } from "../handlers/rejectApplicationHandler";
import type { ApiError } from "../runtime/client";
import type { ApplicationDecisionReasonRequest } from "../types/ApplicationDecisionReasonRequest";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof rejectApplicationHandler>>;
type Vars = { teamPk: TeamPartition; applicationId: string; body: ApplicationDecisionReasonRequest };

export function useRejectApplication(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => rejectApplicationHandler(vars.teamPk, vars.applicationId, vars.body),
    ...options,
  });
}
